<div class="board-stats d-flex gap-3 flex-wrap mb-3 p-3 bg-light rounded">
    <span class="badge bg-primary">Total: @TotalCount</span>
    <span class="badge bg-info text-dark">To Do: @ToDoCount</span>
    <span class="badge bg-warning text-dark">In Progress: @InProgressCount</span>
    <span class="badge bg-success">Done: @DoneCount</span>
    <span class="badge bg-danger">Overdue: @OverdueCount</span>
</div>

@code {
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int ToDoCount { get; set; }
    [Parameter] public int InProgressCount { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int OverdueCount { get; set; }
}

@* Search bar for filtering tasks by title *@

<div class="mb-3">
    <input type="text"
           class="form-control"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

arguments.file_text:
@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Project Board</h3>

@if (loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <BoardStats TotalCount="allTasks.Count"
                ToDoCount="todoTasks.Count"
                InProgressCount="inProgressTasks.Count"
                DoneCount="doneTasks.Count"
                OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <TaskSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board d-flex gap-3">
        <KanbanColumn ColumnName="To Do"
                      Tasks="FilteredTasks(todoTasks)"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="task => MoveTask(task, \"In Progress\")"
                      OnTaskCreated="args => CreateTask(args, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="FilteredTasks(inProgressTasks)"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="task => MoveTask(task, \"To Do\")"
                      OnMoveRight="task => MoveTask(task, \"Done\")"
                      OnTaskCreated="args => CreateTask(args, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="FilteredTasks(doneTasks)"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="task => MoveTask(task, \"In Progress\")"
                      OnTaskCreated="args => CreateTask(args, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> FilteredTasks(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) args, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.kanban-board {
    overflow-x: auto;
}

.kanban-column {
    flex: 1;
    min-width: 280px;
    background-color: #f8f9fa;
    border-radius: 8px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
}

.kanban-column-header h5 {
    margin: 0 0 0.75rem 0;
}

.kanban-column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

.kanban-column-footer {
    margin-top: 0.75rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.task-title {
    font-weight: 600;
}

.priority-badge {
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
}

.priority-high {
    background-color: #dc3545;
    color: #fff;
}

.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-low {
    background-color: #198754;
    color: #fff;
}

.task-card-body {
    display: flex;
    justify-content: space-between;
    font-size: 0.875rem;
    color: #6c757d;
    margin-bottom: 0.5rem;
}

.task-card-actions {
    display: flex;
    gap: 0.5rem;
}

.add-task-form {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

